def digital_person(compact=False, mode='idle'):
    svg=(ROOT/'assets/logistics-assistant.svg').read_text()
    wave='<div class="speech-wave" aria-hidden="true">'+''.join(f'<span style="--i:{i}"></span>' for i in range(7))+'</div>'
    status='正在聆听 · 演示' if mode=='listening' else '在线，随时为你服务'
    return f'<div class="digital-person {"digital-mini" if compact else ""}" data-digital-human data-mode="{mode}"><div class="digital-stage">{svg}</div><h3>后勤小助</h3><p>校园生活的事，随时问我</p><div class="human-status" data-human-status aria-live="polite">{status}</div>{wave}<button class="btn sm" data-speak data-speech="welcome" aria-label="播放数字人欢迎语">'+icon('fa-volume-high')+' 听我介绍</button><button class="btn sm" data-stop-speaking hidden>停止说话</button>'+('' if compact else '<p class="digital-note">数字人演示形象 · 点击可模拟说话</p>')+'</div>'

def enhance_assistant_content(path, content, role, port):
    if role in ['admin','guide'] or 'data-assistant-ui' in content:
        return content
    needs = 'class="composer"' in content or 'data-speak' in content or 'class="voice-layout"' in content or role=='staff' and Path(path).stem=='home'
    if not needs:
        return content
    if port=='pc' and '<div class="companion">' in content:
        start=content.index('<div class="companion">')
        end=content.index('<div class="contact-box">',start)
        content=content[:start]+'<div class="companion digital-companion">'+digital_person()+'</div>'+content[end:]
    if port=='mobile' and '<div class="welcome">' in content:
        content=content.replace('<div class="welcome">','<div class="welcome has-human">',1)
        content=content.replace('<div class="watermark">','<div class="mobile-human">'+digital_person(True)+'</div><div class="watermark">',1)
    if role=='staff' and Path(path).stem=='home':
        content=content.replace('<div class="hero">','<div class="hero assistant-hero"><div class="hero-human">'+digital_person(port=='mobile')+'</div>',1)
        content=content.replace('href="home.html">咨询公开后勤知识','href="assistant.html">咨询公开后勤知识')
    return '<style data-assistant-ui>'+ASSISTANT_CSS+'</style>'+content+'<script>'+(ROOT/'tools/assistant_experience.js').read_text()+'</script>'

def build_assistant_pages():
    for terminal in ['pc','mobile']:
        path=f'staff/{terminal}/home.html'
        old=CONTENTS[path].replace(f'href="../../student/{terminal}/home.html">咨询公开后勤知识', 'href="assistant.html">咨询公开后勤知识').replace('href="home.html">咨询公开后勤知识','href="assistant.html">咨询公开后勤知识')
        PAGES[:]=[p for p in PAGES if p['path']!=path]
        output(path,'教职工服务首页',old,role='staff',port=terminal,active='home')
    for role in ['student','staff','visitor']:
        for port in ['pc','mobile']:
            def out(name,title,body):
                output(f'{role}/{port}/{name}.html',title,body,role=role,port=port,active='home')
            back='assistant.html' if role=='staff' else 'home.html'
            aside='<aside class="voice-assistant">'+digital_person()+'<hr class="divider"><p class="muted">我会把语音整理为文字，确认后再发送。你也可以随时取消，改用键盘输入。</p></aside>'
            title=heading('语音咨询','说出来，也能找到后勤服务',link(back,'返回对话','btn sm','fa-arrow-left'))
            waveform='<div class="record-wave" aria-hidden="true">'+''.join(f'<span style="--i:{i};--h:{[6,15,24,38,50,32,18,12,28,45,24,17][i%12]}"></span>' for i in range(30))+'</div>'
            intro=title+'<div class="voice-layout"><section class="voice-workspace"><div class="voice-topline">语音输入</div><div class="voice-orb">'+icon('fa-microphone')+'</div><h1>把你的问题，说给我听</h1><p>试着说“宿舍水电费怎么缴纳？”<br>识别成文字后，你可以修改并确认发送。</p><div class="voice-mode">'+icon('fa-circle-play')+' 录音样式演示 · 不使用麦克风</div>'+waveform+'<div class="voice-actions">'+link('voice-recording.html','开始录音演示','btn primary','fa-microphone')+link(back,'改为文字输入')+'</div><div class="voice-help"><p>演示包含聆听波形、识别文本和发送确认三个步骤。</p><p>正式语音录入将接入学校语音服务，并在使用前申请麦克风权限。</p></div></section>'+aside+'</div>'
            out('voice','语音输入',intro)
            recording=title+'<div class="voice-layout"><section class="voice-workspace recording-workspace" data-voice-recording><div class="voice-topline">正在聆听 · 演示</div><div class="voice-orb recording">'+icon('fa-microphone')+'</div><h1>慢慢说，我在听</h1><div class="voice-time" id="voice-timer">00:00</div><p id="voice-hint">说完后，点击“结束并识别”</p>'+waveform+'<div class="voice-sentence" id="voice-live-text">正在展示示例识别过程…</div><div class="voice-mode">演示模式 · 未启用麦克风</div><div class="voice-actions">'+link(back,'取消录音')+link('voice-review.html','结束并识别','btn primary','fa-stop')+'</div></section>'+aside.replace('data-mode="idle"','data-mode="listening"').replace('在线，随时为你服务','正在聆听 · 演示')+'</div>'
            out('voice-recording','语音录入中',recording)
            review=title+'<div class="voice-layout"><section class="voice-workspace"><div class="voice-topline">识别完成 · 等待确认</div><div class="voice-orb">'+icon('fa-check')+'</div><h1>这是你想问的吗？</h1><p>检查识别内容，也可以直接修改文字。确认前不会发送问题。</p><form data-submit-chat data-voice-review><label class="voice-review-label" for="question">识别出的文字</label><textarea class="voice-review-input" id="question" name="question" required maxlength="500">宿舍水电费怎么缴纳？</textarea><div class="voice-actions">'+link('voice-recording.html','重新录入')+'<button class="btn primary" type="submit">确认并发送 '+icon('fa-arrow-up')+'</button></div></form><div class="voice-help"><p>以上为示例录音识别结果。正式识别结果由学校语音服务返回。</p></div></section>'+aside+'</div>'
            out('voice-review','语音识别确认',review)
            failure=title+'<div class="voice-layout"><section class="voice-workspace"><div class="voice-orb">'+icon('fa-microphone-slash')+'</div><h1>暂时没有识别到清晰内容</h1><p>请靠近麦克风、减少周围噪声后重试，或改为文字咨询。</p><div class="voice-mode">识别失败状态演示</div><div class="voice-actions">'+link('voice-recording.html','重新录入','btn primary')+link(back,'改为文字输入')+'</div></section>'+aside+'</div>'
            out('voice-error','语音识别失败',failure)
            if role=='staff':
                content=CONTENTS[f'student/{port}/home.html'].replace('同学你好，今天有什么可以帮你？','老师你好，今天有什么可以帮你？')
                out('assistant','教职工智能问答',content)
